function checklist(opts){
  opts=opts||{};
  var title=(opts.title||'检查清单').trim()||'检查清单';
  var groups=String(opts.groups||'').split(/\n/).map(function(s){return s.trim();}).filter(Boolean);
  if(!groups.length) groups=['准备','执行','收尾'];
  var L=['# '+title,''];
  for(var g=0;g<groups.length;g++){
    var parts=groups[g].split(/\s*[:：]\s*/);
    var gname=(parts[0]||'').trim() || ('步骤 '+(g+1));
    var raw=parts.length>1 ? parts.slice(1).join(' ') : '';
    var gitems=raw.split(/[、,，;；]/).map(function(x){return x.trim();}).filter(Boolean);
    L.push('## '+gname);
    if(gitems.length){ for(var i=0;i<gitems.length;i++) L.push('- [ ] '+gitems[i]); }
    else { L.push('- [ ] ____'); }
    L.push('');
  }
  return L.join('\n').replace(/\n+$/,'');
}

var EXPORTS={checklist:checklist};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.ChecklistForgePure = EXPORTS; }
